(* [comment removed for export] *)
Definition casc_fill_exit (ra sp gp tp s0 s1 s2 s4 s5 s6 s7 s8 s10 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (tab : Z)
    : machine_state -> Prop :=
  fun ms' => exists (a7' t0' t1' t2' t3' t4' t5' : word) (m' : mem) (bs' : list byte),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 (tab + 256)) (Z_to_bv 64 256) (Z_to_bv 64 2048) (Z_to_bv 64 1024) (Z_to_bv 64 512) (Z_to_bv 64 1) (Z_to_bv 64 (tab + 256)) a7'
                  s2 (Z_to_bv 64 0) s4 s5 s6 s7 s8 (Z_to_bv 64 tab) s10 (Z_to_bv 64 SHB) t3' t4' t5' t6)
             F (Z_to_bv 64 0x170db0) fc None m' (seg_rom asegs)
    /\ munch [(tab, tab + 256)] m m' /\ wmono asegs m m' /\ mem_inv asegs m' /\ u8arr asegs m' tab bs' /\ Z.of_nat (length bs') = 256.

(* [comment removed for export] *)
Lemma casc_fill : forall (k : nat) (i : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a6 a7 s2 s3 s4 s5 s6 s7 s8 s10 t3 t4 t5 t6 : word) F fc (m : mem) (tab : Z) (bs : list byte),
  a0 = Z_to_bv 64 (tab + i) -> a6 = Z_to_bv 64 (tab + i) -> a1 = Z_to_bv 64 i -> a2 = Z_to_bv 64 (8 * i) -> a3 = Z_to_bv 64 (4 * i) -> a4 = Z_to_bv 64 (2 * i) ->
  s3 = Z_to_bv 64 (256 - i) ->
  Z.of_nat k = 256 - i -> 0 <= i -> (1 <= k)%nat ->
  0 < tab -> tab mod 16 = 0 -> tab + 256 <= 2^47 -> (tab + 256 <= 0x7fff7000 \/ 0x10007fff8000 <= tab) ->
  u8arr asegs m tab bs -> Z.of_nat (length bs) = 256 ->
  acc asegs m tab 256 -> mem_inv asegs m ->
  evt asegs (casc_fill_exit ra sp gp tp s0 s1 s2 s4 s5 s6 s7 s8 s10 t6 F fc m tab)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 (Z_to_bv 64 1) a6 a7
             s2 s3 s4 s5 s6 s7 s8 (Z_to_bv 64 tab) s10 (Z_to_bv 64 SHB) t3 t4 t5 t6)
        F (Z_to_bv 64 0x170d28) fc None m (seg_rom asegs)).
